from pathlib import Path

p = Path('src/main.jsx')
s = p.read_text()
if 'function Fluxo(' in s:
    print('Finance components already present')
    raise SystemExit(0)

components = r'''
function Section({title,children,action}){return <section className="card"><div className="section-title"><h2>{title}</h2>{action}</div>{children}</section>}
function Row({label,value,onChange,auto=false,action}){return <div className="row"><span>{label}{auto&&<em> automático</em>}</span><input type="number" value={Number(value||0)} onChange={e=>onChange?.(Number(e.target.value)||0)} disabled={auto}/>{action}</div>}
function Kpi({t,v,kind}){return <div className="kpi"><span>{t}</span><strong>{kind==='count'?Number(v||0):t.toLowerCase().includes('compromet')?`${Number(v||0).toFixed(1)}%`:BRL(v)}</strong></div>}
function MonthSelect({month,setMonth,months=MONTHS}){const all=[...new Set(months.concat(month))].filter(Boolean).sort();return <label>Mês de referência<select value={month} onChange={e=>setMonth(e.target.value)}>{all.map(m=><option key={m}>{m}</option>)}</select></label>}
function Fluxo({data,month,setMonth,updateFlux,addSeries,updateSeries,stopSeries}){const f=data.fluxo.find(x=>x.month===month)||{},extras=data.entradas.filter(x=>x.month===month&&x.ativo!==false),custom=data.despesas.filter(x=>x.month===month&&x.ativo!==false),fm=calcFluxoMonth(f,data.prestadores.filter(p=>p.month===month&&p.ativo!==false),custom,extras);return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.fluxo.map(x=>x.month)}/></div><div className="kpis"><Kpi t="Entradas" v={fm.entries}/><Kpi t="Despesas" v={fm.expenses}/><Kpi t="Saldo" v={fm.balance}/></div><div className="grid2"><Section title="Entradas"><Row label="Salário" value={f.salario} onChange={v=>updateFlux({salario:v})}/><Row label="VA" value={f.va} onChange={v=>updateFlux({va:v})}/>{extras.map(x=><Row key={x.id} label={x.nome} value={x.valor} onChange={v=>updateSeries('entradas',x.id,{valor:v})} action={<button className="ghost" onClick={()=>stopSeries('entradas',x.series_id||x.id)}>Encerrar</button>}/>)}<button className="secondary" onClick={()=>{const n=prompt('Nome da nova entrada');if(n){const v=prompt('Valor mensal');if(v!==null)addSeries('entradas',n,v)}}}>+ Nova entrada</button><div className="total">Total <b>{BRL(fm.entries)}</b></div></Section><Section title="Despesas"><div className="note">Prestadores e imposto entram automaticamente. Encerrar preserva o histórico.</div>{FLUXO_FIELDS.map(([k,l])=><Row key={k} label={l} value={f[k]} onChange={v=>updateFlux({[k]:v})/>)}{custom.map(x=><Row key={x.id} label={x.nome} value={x.valor} onChange={v=>updateSeries('despesas',x.id,{valor:v})} action={<button className="ghost" onClick={()=>stopSeries('despesas',x.series_id||x.id)}>Encerrar</button>}/>)}<Row label="Prestadores de Serviço" value={fm.employeeTotal} auto/><Row label="Imposto" value={fm.tax} auto/><button className="secondary" onClick={()=>{const n=prompt('Nome da nova despesa');if(n){const v=prompt('Valor mensal');if(v!==null)addSeries('despesas',n,v)}}}>+ Nova conta</button></Section></div></>}
function Prestadores({data,save,month,setMonth}){const rows=data.prestadores.filter(x=>x.month===month&&x.ativo!==false),total=rows.reduce((s,x)=>s+totalPrestador(x),0);const add=()=>{const nome=prompt('Nome do prestador');if(!nome)return;const sid=crypto.randomUUID();const next=[...data.prestadores,...planningMonths(month,12).map(m=>({id:crypto.randomUUID(),prestador_id:sid,month:m,nome,salario:1400,dias_uteis:22,passagem_scs:0,passagem_sp:0,ativo:true}))];save({...data,prestadores:next})};const update=(id,p)=>save({...data,prestadores:data.prestadores.map(x=>x.id===id?{...x,...p}:x)});return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.prestadores.map(x=>x.month)}/><button className="primary" onClick={add}>+ Prestador</button></div><Section title="Prestadores"><div className="kpis"><Kpi t="Custo mensal" v={total}/><Kpi t="Quantidade" v={rows.length} kind="count"/></div>{rows.map(p=>{const pct=total?totalPrestador(p)/total*100:0;return <div className="card provider-card" key={p.id}><div className="provider-head"><div><strong>{p.nome||'Prestador'}</strong><span>Participação no custo</span></div><b>{pct.toFixed(1)}%</b></div><Row label="Salário" value={p.salario} onChange={v=>update(p.id,{salario:v})}/><Row label="Dias úteis" value={p.dias_uteis} onChange={v=>update(p.id,{dias_uteis:v})}/><Row label="Passagem SCS" value={p.passagem_scs} onChange={v=>update(p.id,{passagem_scs:v})}/><Row label="Passagem SP" value={p.passagem_sp} onChange={v=>update(p.id,{passagem_sp:v})}/><div className="provider-share"><span>Participação no total</span><strong>{pct.toFixed(1)}%</strong></div><div className="total">Custo calculado <b>{BRL(totalPrestador(p))}</b></div></div>})}{!rows.length&&<div className="empty">Nenhum prestador neste mês.</div>}</Section></>}
function transferOptions(data,month){const f=data.fluxo.find(x=>x.month===month)||{};const fixed=FLUXO_FIELDS.map(([key,label])=>({id:`fluxo:${key}`,label,value:Number(f[key]||0)}));const custom=data.despesas.filter(x=>x.month===month&&x.ativo!==false).map(x=>({id:`despesa:${x.id}`,label:x.nome,value:Number(x.valor||0)}));return [...fixed,...custom].filter(x=>x.value>0)}
function transferValue(t,data,month){const options=transferOptions(data,month),refs=t.expenseRefs||[];if(!refs.length)return Number(t.valor||0);return refs.reduce((s,id)=>s+(options.find(o=>o.id===id)?.value||0),0)}
function Transferencias({data,save,month,setMonth}){const rows=data.transferencias.filter(x=>x.month===month&&x.ativo!==false),options=transferOptions(data,month),[editing,setEditing]=useState(null);const open=t=>setEditing(t?{...t,expenseRefs:[...(t.expenseRefs||[])]}:{id:null,nome:'',expenseRefs:[]});const close=()=>setEditing(null);const toggle=id=>setEditing(x=>({...x,expenseRefs:x.expenseRefs.includes(id)?x.expenseRefs.filter(v=>v!==id):[...x.expenseRefs,id]}));const total=editing?.expenseRefs.reduce((s,id)=>s+(options.find(o=>o.id===id)?.value||0),0)||0;const saveTransfer=()=>{if(!editing?.nome?.trim()||!editing.expenseRefs.length)return;const value=total;if(editing.id){save({...data,transferencias:data.transferencias.map(x=>x.id===editing.id?{...x,nome:editing.nome.trim(),expenseRefs:editing.expenseRefs,valor:value}:x)})}else{const id=crypto.randomUUID();save({...data,transferencias:[...data.transferencias,{id,series_id:id,month,nome:editing.nome.trim(),expenseRefs:editing.expenseRefs,valor:value,ativo:true}]})}close()};const remove=id=>save({...data,transferencias:data.transferencias.map(x=>x.id===id?{...x,ativo:false}:x)});return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.transferencias.map(x=>x.month)}/><button className="primary" onClick={()=>open()}>+ Transferência</button></div><Section title="Transferências"><div className="note">Selecione as despesas do Fluxo que compõem cada transferência. O valor é calculado automaticamente pela soma das despesas selecionadas.</div>{rows.map(t=>{const value=transferValue(t,data,month);return <div className="transfer-card" key={t.id}><div><strong>{t.nome}</strong><span>{(t.expenseRefs||[]).length} despesa(s) vinculada(s)</span></div><b>{BRL(value)}</b><button className="ghost" onClick={()=>open(t)}>Editar</button><button className="ghost" onClick={()=>remove(t.id)}>Encerrar</button></div>})}{!rows.length&&<div className="empty">Nenhuma transferência neste mês.</div>}</Section>{editing&&<Modal title={editing.id?'Editar transferência':'Nova transferência'} onClose={close} onSave={saveTransfer} saveLabel="Salvar"><FormField label="Nome da transferência"><input autoFocus value={editing.nome} onChange={e=>setEditing(x=>({...x,nome:e.target.value}))} placeholder="Ex.: Cartão / Conta conjunta"/></FormField><div className="selection-total"><span>Valor calculado</span><strong>{BRL(total)}</strong></div><div className="expense-picker">{options.map(o=><label key={o.id} className="expense-option"><input type="checkbox" checked={editing.expenseRefs.includes(o.id)} onChange={()=>toggle(o.id)}/><span>{o.label}</span><b>{BRL(o.value)}</b></label>)}</div>{!options.length&&<div className="empty">Nenhuma despesa com valor disponível no Fluxo deste mês.</div>}</Modal>}</>}
function Budget({data,save,month,setMonth}){const accounts=data.budgetAccounts.filter(a=>a.month===month&&a.ativo!==false),spent=a=>data.gastos.filter(g=>g.month===month&&g.budget_account_id===a.id).reduce((s,g)=>s+Number(g.valor||0),0),totalBudget=accounts.reduce((s,a)=>s+Number(a.budget||0),0),totalSpent=accounts.reduce((s,a)=>s+spent(a),0);const addAccount=()=>{const nome=prompt('Nome da nova conta');if(!nome?.trim())return;const budget=Number((prompt('Budget mensal')||'0').replace(',','.'));if(!Number.isFinite(budget)||budget<0)return;save({...data,budgetAccounts:[...data.budgetAccounts,{id:crypto.randomUUID(),month,nome:nome.trim(),budget,ativo:true}]})};const addGasto=a=>{const v=Number((prompt(`Valor lançado em ${a.nome}`)||'0').replace(',','.'));if(!v)return;save({...data,gastos:[...data.gastos,{id:crypto.randomUUID(),month,conta:a.legacy_key||a.id,budget_account_id:a.id,valor:Math.abs(v)}]})};const update=(id,budget)=>save({...data,budgetAccounts:data.budgetAccounts.map(a=>a.id===id?{...a,budget}:a)});const removeGasto=id=>save({...data,gastos:data.gastos.filter(g=>g.id!==id)});return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.budgetAccounts.map(x=>x.month)}/><button className="primary" onClick={addAccount}>+ Conta</button></div><div className="budget-summary"><Kpi t="Budget total" v={totalBudget}/><Kpi t="Realizado" v={totalSpent}/><Kpi t="Disponível" v={totalBudget-totalSpent}/></div><div className="budgetgrid">{accounts.map(a=>{const gastos=data.gastos.filter(g=>g.month===month&&g.budget_account_id===a.id),used=spent(a),remaining=Number(a.budget||0)-used,pct=a.budget?Math.min(100,used/a.budget*100):0;return <section className="card budget-card" key={a.id}><div className="section-title"><h2>{a.nome}</h2><button className="ghost" onClick={()=>{const v=prompt('Novo budget',a.budget);if(v!==null)update(a.id,Number(v.replace(',','.'))||0)}}>Editar</button></div><div className="budget-values"><div><span>Budget</span><strong>{BRL(a.budget)}</strong></div><div><span>Lançado</span><strong>{BRL(used)}</strong></div><div><span>Disponível</span><strong className={remaining<0?'negative':''}>{BRL(remaining)}</strong></div></div><div className="budget-progress"><i style={{width:`${pct}%`}}/></div>{gastos.length>0&&<div className="budget-launches">{gastos.map(g=><div key={g.id}><span>Lançamento</span><b>{BRL(g.valor)}</b><button className="icon-button" onClick={()=>removeGasto(g.id)}>×</button></div>)}</div>}<button className="secondary" onClick={()=>addGasto(a)}>+ Lançamento</button></section>})}</div></>}
function Dash({data,month,setMonth}){const[view,setView]=useState('fluxo');return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.fluxo.map(x=>x.month)}/><div className="dash-switch"><button className={view==='fluxo'?'primary':'ghost'} onClick={()=>setView('fluxo')}>Fluxo</button><button className={view==='budget'?'primary':'ghost'} onClick={()=>setView('budget')}>Budget</button></div></div>{view==='fluxo'?<DashFluxo data={data} month={month} setMonth={setMonth}/>:<DashBudget data={data} month={month}/>}</>}
function DashFluxo({data,month,setMonth}){const refMonth=month||currentMonth(),months=planningMonths(refMonth,12),rows=months.map(m=>{const f=data.fluxo.find(x=>x.month===m)||{},prest=data.prestadores.filter(x=>x.month===m&&x.ativo!==false),entradas=data.entradas.filter(x=>x.month===m&&x.ativo!==false),despesas=data.despesas.filter(x=>x.month===m&&x.ativo!==false);return {m,...calcFluxoMonth(f,prest,despesas,entradas)}}),current=rows.find(x=>x.m===refMonth)||rows[0],negative=rows.filter(x=>x.balance<0).length,best=[...rows].sort((a,b)=>b.balance-a.balance)[0],worst=[...rows].sort((a,b)=>a.balance-b.balance)[0],avg=rows.slice(1).reduce((s,x)=>s+x.balance,0)/Math.max(1,rows.length-1);const expenseMap=new Map(),f=data.fluxo.find(x=>x.month===refMonth)||{};FLUXO_FIELDS.forEach(([k,l])=>{const v=Number(f[k]||0);if(v)expenseMap.set(l,v)});data.despesas.filter(x=>x.month===refMonth&&x.ativo!==false).forEach(x=>{const v=Number(x.valor||0);expenseMap.set(x.nome,(expenseMap.get(x.nome)||0)+v)});const top=[...expenseMap.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5),top3=top.slice(0,3).reduce((s,x)=>s+x[1],0),allExp=[...expenseMap.values()].reduce((s,v)=>s+v,0),maxAbs=Math.max(1,...rows.map(r=>Math.abs(r.balance)));return <div className="dash-content"><div className="kpis"><Kpi t="Entradas do mês" v={current.entries}/><Kpi t="Despesas do mês" v={current.expenses}/><Kpi t="Saldo do mês" v={current.balance}/><Kpi t="Meses negativos" v={negative} kind="count"/></div><div className="grid2"><Section title="Leitura executiva"><div className="dash-insight"><b>Caixa projetado</b><span>Saldo médio dos próximos 11 meses: <strong>{BRL(avg)}</strong></span></div><div className="dash-insight"><b>Melhor mês</b><span>{best.m} · <strong>{BRL(best.balance)}</strong></span></div><div className="dash-insight"><b>Pior mês</b><span>{worst.m} · <strong className={worst.balance<0?'negative':''}>{BRL(worst.balance)}</strong></span></div><div className="dash-insight"><b>Concentração</b><span>Top 3 despesas representam <strong>{allExp?(top3/allExp*100).toFixed(1):'0.0'}%</strong> do fluxo fixo considerado.</span></div></Section><Section title="Maiores despesas"><div className="dash-ranking">{top.map(([name,value],i)=><div key={name}><span><b>{i+1}</b>{name}</span><strong>{BRL(value)}</strong></div>)}</div>{!top.length&&<div className="empty">Nenhuma despesa registrada.</div>}</Section></div><Section title={`Evolução do saldo · ${refMonth} + 11 meses`}><div className="dash-trend">{rows.map(x=><div key={x.m} className={x.balance<0?'negative':''}><span>{x.m.slice(5)}</span><i style={{height:`${Math.max(7,Math.abs(x.balance)/maxAbs*100)}%`}}/><small>{BRL(x.balance)}</small></div>)}</div></Section><Section title="Visão mensal"><div className="table-wrap"><table><thead><tr><th>Mês</th><th>Entradas</th><th>Despesas</th><th>Saldo</th></tr></thead><tbody>{rows.map(x=><tr key={x.m}><td>{x.m}</td><td>{BRL(x.entries)}</td><td>{BRL(x.expenses)}</td><td className={x.balance<0?'negative':''}>{BRL(x.balance)}</td></tr>)}</tbody></table></div></Section></div>}
function DashBudget({data,month}){const accounts=data.budgetAccounts.filter(a=>a.month===month&&a.ativo!==false),rows=accounts.map(a=>{const spent=data.gastos.filter(g=>g.month===month&&g.budget_account_id===a.id).reduce((s,g)=>s+Number(g.valor||0),0);return {...a,spent,remaining:Number(a.budget||0)-spent}}),budget=rows.reduce((s,a)=>s+Number(a.budget||0),0),spent=rows.reduce((s,a)=>s+a.spent,0),pct=budget?spent/budget*100:0;return <div className="dash-content"><div className="kpis"><Kpi t="Budget" v={budget}/><Kpi t="Realizado" v={spent}/><Kpi t="Disponível" v={budget-spent}/><Kpi t="Uso do budget" v={pct}/></div><Section title={`Acompanhamento por conta · ${month}`}><div className="budget-trend">{rows.map(a=><div key={a.id}><span>{a.nome}</span><div><i style={{width:`${Math.min(100,Math.max(0,a.budget? a.spent/a.budget*100:0))}%`}}/><b>{BRL(a.spent)}</b><small>{BRL(a.remaining)} disponível</small></div></div>)}</div></Section></div>}
'''
marker="\nconst root=document.getElementById('root')"
if marker not in s:
    raise SystemExit('React root marker not found')
s=s.replace(marker,'\n'+components+marker,1)
p.write_text(s)
print('Restored enhanced Finance components before React root')